package com.bank.ledger.model;

import jakarta.persistence.*;
import org.hibernate.annotations.UuidGenerator;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.UUID;

@Entity
@Table(name = "ledger_transactions")
public class LedgerTransaction {

    // (Recommended) TIME-ORDERED UUID (UUIDv7-style): high bits encode time → inserts APPEND
    //    avoids B-tree page splits, index fragmentation, and cache thrash.
    // (Avoid) DO NOT use GenerationType.UUID here — that is random v4 and scatters inserts.
    @Id
    @UuidGenerator(style = UuidGenerator.Style.TIME)
    private UUID id;

    @Column(name = "account_id", nullable = false)
    private String accountId;

    @Column(nullable = false, precision = 15, scale = 2)
    private BigDecimal amount;

    @Column(nullable = false)
    private String direction;

    @Column(name = "created_at")
    private LocalDateTime createdAt;

    protected LedgerTransaction() {}

    public LedgerTransaction(String accountId, BigDecimal amount, String direction) {
        this.accountId = accountId;
        this.amount = amount;
        this.direction = direction;
        this.createdAt = LocalDateTime.now();
    }

    public UUID getId() { return id; }
    public String getAccountId() { return accountId; }
    public BigDecimal getAmount() { return amount; }
    public String getDirection() { return direction; }
}
