// Demonstrates WHY time-ordered ids append while random v4 ids scatter.
package com.bank.ledger.id;

import java.security.SecureRandom;
import java.util.UUID;

public final class TimeOrderedIds {

    private static final SecureRandom RANDOM = new SecureRandom();

    private TimeOrderedIds() {}

    // Minimal UUIDv7-style generator: 48-bit millisecond timestamp in the high bits,
    // then random bits. Values created later sort AFTER earlier ones as unsigned bytes.
    public static UUID uuidV7() {
        long ts = System.currentTimeMillis();           // 48-bit timestamp
        byte[] b = new byte[16];
        b[0] = (byte) (ts >>> 40);
        b[1] = (byte) (ts >>> 32);
        b[2] = (byte) (ts >>> 24);
        b[3] = (byte) (ts >>> 16);
        b[4] = (byte) (ts >>> 8);
        b[5] = (byte) ts;
        byte[] rnd = new byte[10];
        RANDOM.nextBytes(rnd);
        System.arraycopy(rnd, 0, b, 6, 10);
        b[6] = (byte) ((b[6] & 0x0F) | 0x70);            // version 7
        b[8] = (byte) ((b[8] & 0x3F) | 0x80);            // variant
        long msb = 0, lsb = 0;
        for (int i = 0; i < 8; i++) msb = (msb << 8) | (b[i] & 0xFF);
        for (int i = 8; i < 16; i++) lsb = (lsb << 8) | (b[i] & 0xFF);
        return new UUID(msb, lsb);
    }

    // Random v4 — no ordering; used ONLY to show the contrast.
    public static UUID randomV4() { return UUID.randomUUID(); }
}
