package com.bank.ledger.service;

import com.bank.ledger.dto.IdOrderingReport;
import com.bank.ledger.id.TimeOrderedIds;
import com.bank.ledger.model.LedgerTransaction;
import com.bank.ledger.repository.LedgerTransactionRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.IntStream;

@Service
@RequiredArgsConstructor
@Slf4j
public class LedgerService {

    private final LedgerTransactionRepository ledgerRepo;

    @Transactional
    public int recordBatch(String accountId, int count) {
        List<LedgerTransaction> txns = IntStream.rangeClosed(1, count)
            .mapToObj(i -> new LedgerTransaction(accountId, new BigDecimal("1000"),
                i % 2 == 0 ? "CREDIT" : "DEBIT"))
            .toList();
        ledgerRepo.saveAll(txns);
        // Time-ordered PKs mean these INSERTs append near the end of the index → no page splits
        log.info("Recorded {} txns for {} — time-ordered PKs append (no fragmentation)", count, accountId);
        return count;
    }

    // Demonstrates the ordering property that makes inserts append vs scatter
    public IdOrderingReport demonstrateOrdering(int n) {
        List<String> timeOrdered = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            timeOrdered.add(TimeOrderedIds.uuidV7().toString());
            try { Thread.sleep(2); } catch (InterruptedException ignored) { Thread.currentThread().interrupt(); }
        }
        List<String> randomV4 = IntStream.range(0, n)
            .mapToObj(i -> TimeOrderedIds.randomV4().toString()).toList();

        boolean timeSorted = isSorted(timeOrdered);
        boolean randomSorted = isSorted(randomV4);

        log.info("Time-ordered ids sorted-as-generated={} ; random v4 sorted={}", timeSorted, randomSorted);
        return new IdOrderingReport(timeOrdered, timeSorted, randomV4, randomSorted,
            "Time-ordered ids append (sorted); random v4 scatters → B-tree page splits & index bloat");
    }

    private boolean isSorted(List<String> ids) {
        for (int i = 1; i < ids.size(); i++) {
            if (ids.get(i - 1).compareTo(ids.get(i)) > 0) return false;
        }
        return true;
    }
}
