import java.util.Map;

@RestController
@RequestMapping("/api/v1/ledger")
@RequiredArgsConstructor
public class LedgerController {

    private final LedgerService service;

    @PostMapping("/{accountId}/record")
    public Map<String, Object> record(@PathVariable String accountId,
                                       @RequestParam(defaultValue = "100") int count) {
        return Map.of("accountId", accountId, "recorded", service.recordBatch(accountId, count));
    }

    @GetMapping("/id-ordering")
    public IdOrderingReport ordering(@RequestParam(defaultValue = "5") int n) {
        return service.demonstrateOrdering(n);
    }
}
