package com.bank.ledger.id;

import org.junit.jupiter.api.Test;
import java.util.*;
import static org.assertj.core.api.Assertions.*;

class IdOrderingTest {

    @Test
    void timeOrderedIdsSortByGenerationTime() throws InterruptedException {
        List<String> ids = new ArrayList<>();
        for (int i = 0; i < 20; i++) {
            ids.add(TimeOrderedIds.uuidV7().toString());
            Thread.sleep(2);  // ensure the millisecond timestamp advances
        }
        List<String> sorted = new ArrayList<>(ids);
        Collections.sort(sorted);
        // generated order == sorted order → inserts APPEND at the end of the index
        assertThat(ids).isEqualTo(sorted);
    }

    @Test
    void randomV4IsAlmostNeverSorted() {
        List<String> ids = new ArrayList<>();
        for (int i = 0; i < 50; i++) ids.add(TimeOrderedIds.randomV4().toString());
        List<String> sorted = new ArrayList<>(ids);
        Collections.sort(sorted);
        // random v4 generation order ≠ sorted order → inserts SCATTER (page splits)
        assertThat(ids).isNotEqualTo(sorted);
    }

    @Test
    void uuidV7IsVersion7() {
        assertThat(TimeOrderedIds.uuidV7().version()).isEqualTo(7);
    }

    @Test
    void smallerPkMeansSmallerSecondaryIndexes() {
        // InnoDB: every secondary index stores the full PK.
        // 8-byte bigint vs 16-byte UUID → UUID doubles every secondary index's key size.
        int bigintBytes = 8, uuidBytes = 16;
        assertThat(uuidBytes).isGreaterThan(bigintBytes);
    }
}
